// routes/extracto.js — Extracto de carreras (boleto) desde datos reales
const { Chofer, Viaje } = require("../db/models");
const TPL = Buffer.from("","base64").toString("utf8");
const MESL=["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"];
const DOW=["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"];
const OFF=-4*3600*1000, bo=d=>new Date(new Date(d).getTime()+OFF), pad=n=>("0"+n).slice(-2);
const esComp=v=>v.fechaFin&&!/cancel|rechaz|buscando|timeout|zombie/i.test(v.estado||"");
module.exports=(app)=>{
  app.get("/extracto/:phone",async(req,res)=>{
    try{
      const phone=String(req.params.phone).replace(/\D/g,"");
      const chofer=await Chofer.findUnique({where:{phone}});
      if(!chofer) return res.status(404).send("Conductor no encontrado: "+phone);
      const viajes=await Viaje.findMany({where:{choferPhone:phone},orderBy:{fechaInicio:"asc"}});
      const comp=viajes.filter(esComp);
      const totBs=comp.reduce((a,v)=>a+(v.precioTotal||0),0), totKm=comp.reduce((a,v)=>a+(v.distanciaKm||0),0);
      const diasSet=new Set(comp.map(v=>bo(v.fechaFin).toISOString().slice(0,10)));
      const cancel=viajes.filter(v=>/cancel|rechaz/i.test(v.estado||"")).length;
      const cuota=diasSet.size*10, neto=totBs-cuota, prom=comp.length?totBs/comp.length:0;
      const acept=(comp.length+cancel)?Math.round(comp.length/(comp.length+cancel)*100):100;
      const mm={};comp.forEach(v=>{const d=bo(v.fechaFin),k=d.getUTCFullYear()+"-"+d.getUTCMonth();(mm[k]=mm[k]||{y:d.getUTCFullYear(),mo:d.getUTCMonth(),viajes:0,ingresos:0});mm[k].viajes++;mm[k].ingresos+=v.precioTotal||0;});
      const meses=Object.values(mm).sort((a,b)=>a.y-b.y||a.mo-b.mo).slice(-6).map(x=>({m:MESL[x.mo],viajes:x.viajes,ingresos:Math.round(x.ingresos)}));
      const dc=[0,0,0,0,0,0,0];comp.forEach(v=>{dc[bo(v.fechaFin).getUTCDay()]++;});
      const dias=[1,2,3,4,5,6,0].map(i=>({d:DOW[i],v:dc[i]}));
      const items=comp.slice().reverse().slice(0,8).map(v=>{const d=bo(v.fechaFin);return [pad(d.getUTCDate())+"/"+pad(d.getUTCMonth()+1)+" "+pad(d.getUTCHours())+":"+pad(d.getUTCMinutes()),(v.origenNombre||"?").split(",")[0].slice(0,22),(v.destinoNombre||"?").split(",")[0].slice(0,22),Math.round((v.distanciaKm||0)*10)/10,Math.round(v.precioTotal||0),Math.round(v.ratingPasajero||5)];});
      const fsA=comp.map(v=>bo(v.fechaFin).getTime());
      const min=fsA.length?new Date(Math.min(...fsA)):bo(Date.now()), max=fsA.length?new Date(Math.max(...fsA)):bo(Date.now());
      const period=pad(min.getUTCDate())+" "+MESL[min.getUTCMonth()].toUpperCase()+" — "+pad(max.getUTCDate())+" "+MESL[max.getUTCMonth()].toUpperCase()+" "+max.getUTCFullYear();
      const alta=chofer.fechaRegistro?bo(chofer.fechaRegistro):null, antig=alta?(MESL[alta.getUTCMonth()]+" "+alta.getUTCFullYear()):"—";
      const nombre=chofer.nombre||"Conductor", apellido=(nombre.split(" ").slice(-1)[0]||"").toUpperCase();
      const data={nombre,apellido,veh:(chofer.tipoVehiculo==="moto"?"Moto":"Auto"),
        vehUp:((chofer.tipoVehiculo==="moto"?"MOTO":"AUTO")+(chofer.colorVehiculo?(" · "+chofer.colorVehiculo.toUpperCase()):"")),
        color:chofer.colorVehiculo||"—",placa:(chofer.placa||"—").replace(/^(\w{4})(\w+)$/,"$1 $2"),
        rating:(chofer.ratingPromedio||0).toFixed(1),ratingN:chofer.ratingCantidad||comp.length,antig,
        folio:"CG-"+(chofer.placa||"0000").replace(/\W/g,"").slice(0,4)+"-"+pad(max.getUTCMonth()+1)+String(max.getUTCFullYear()).slice(-2),
        emision:pad(bo(Date.now()).getUTCDate())+"/"+pad(bo(Date.now()).getUTCMonth()+1)+"/"+bo(Date.now()).getUTCFullYear(),
        period,periodSub:(meses.length+" "+(meses.length===1?"mes":"meses")),
        k:{viajes:comp.length,ingresos:Math.round(totBs),neto:Math.round(neto),km:Math.round(totKm),prom:String(Math.round(prom*10)/10).replace(".",","),dias:diasSet.size,cancel,cuota,acept,porMes:(meses.length?Math.round(comp.length/meses.length):0)},
        meses,dias,items};
      res.set("Content-Type","text/html; charset=utf-8").send(TPL.replace("__DATA_JSON__",()=>JSON.stringify(data)));
    }catch(e){ res.status(500).send("Error extracto: "+e.message); }
  });
};
